INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Registrar lead en CRM', 'accion', 'Registrar nombre, teléfono, producto consultado, zona y canal de origen.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Asignarse como responsable', 'accion', 'Orden de llegada obligatorio. No hay excusas.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Ver producto consultado', 'accion', 'Identificar qué producto o categoría consultó.', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Ver zona productiva', 'accion', 'Identificar zona productiva para evaluar logística.', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Identificar si ya es cliente', 'verificacion', 'Buscar en el CRM si ya tiene historial.', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Revisar historial de compras', 'accion', 'Si existe, revisar compras anteriores.', false, 5);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('9fceea60-80b8-4957-86bc-587852b4939f', 'Contactar dentro del tiempo máximo', 'verificacion', 'Ideal: < 15 min. Aceptable: < 1 hora.', true, 6);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar cultivo', 'verificacion', '¿Qué cultivo está trabajando?', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar superficie', 'verificacion', '¿Cuántas hectáreas?', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar zona', 'verificacion', '¿En qué zona productiva?', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar momento del ciclo', 'verificacion', '¿En qué estado está hoy el lote?', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar si ya tiene proveedor', 'verificacion', '¿Ya viene trabajando con otro proveedor?', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Confirmar nivel de decisión', 'verificacion', '¿Está en condiciones de definir ahora?', true, 5);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('628ae25f-3eff-498d-9573-a68b5b2719e8', 'Definir próximo paso', 'accion', 'Cotización, visita o reunión. Siempre con día y hora.', true, 6);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('427c93bf-4902-4196-8ca0-c8a7a3cce717', 'Llamado inicial', 'accion', 'Primer intento de contacto telefónico.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('427c93bf-4902-4196-8ca0-c8a7a3cce717', 'WhatsApp inmediato', 'accion', 'Mensaje de WhatsApp inmediato tras llamado fallido.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('427c93bf-4902-4196-8ca0-c8a7a3cce717', 'Segundo intento de llamado', 'accion', 'Segundo intento telefónico.', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('427c93bf-4902-4196-8ca0-c8a7a3cce717', 'Último mensaje de cierre', 'accion', 'Mensaje final antes de descartar.', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('427c93bf-4902-4196-8ca0-c8a7a3cce717', 'Descarte formal', 'accion', 'Registrar motivo: No contacto.', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Determinar volumen', 'verificacion', '¿Tiene volumen atractivo?', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Evaluar momento de decisión', 'verificacion', '¿Está en momento de decisión?', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Evaluar si vale visita', 'verificacion', '¿Justifica visita a campo?', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Descartar precio-shopping', 'verificacion', '¿Solo pide precio sin datos?', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Clasificar perfil de cliente', 'accion', 'Productor chico/medio/grande, Contratista, Ingeniero asesor.', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('d4172612-648d-4757-9d06-f43ac0d8547b', 'Registrar perfil y decisión', 'accion', 'Registrar clasificación en CRM.', true, 5);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'Apertura de la visita', 'accion', 'Ver el lote y entender antes de hablar de números.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'SPIN - Situación', 'pregunta', '¿Qué venís aplicando hoy?', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'SPIN - Problema', 'pregunta', '¿Qué problema puntual estás viendo?', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'SPIN - Implicación', 'pregunta', 'Si no lo corregís ahora, ¿qué impacto en rendimiento?', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'SPIN - Necesidad', 'pregunta', '¿Qué resultado esperás lograr?', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'Registrar diagnóstico', 'accion', 'Problema, riesgo, rendimiento esperado, presupuesto.', true, 5);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'Presentar solución', 'accion', '1 solución principal, máx 2 alternativas. No 10 productos.', true, 6);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c20aad36-f2bf-495a-8346-a0370e3263cd', 'Definir avance', 'verificacion', 'Sí → Cotización. Duda → Zona gris. No → Descarte.', true, 7);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c50a5b85-c79c-46b3-854c-72a2695517b7', 'Agendar próxima acción', 'accion', 'Siempre dejar acción agendada. Máximo 7 días.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c50a5b85-c79c-46b3-854c-72a2695517b7', 'Reencuadrar la situación', 'accion', 'Script de reencuadre para definir avance o pausa.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('c50a5b85-c79c-46b3-854c-72a2695517b7', 'Reglas de zona gris', 'tip', 'NO bajar precio sin criterio. NO competir por WhatsApp. NO mandar lista completa. NO descontar sin volumen.', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('25dbec47-70dd-468a-a361-9bd8876ca491', 'Intento de cierre', 'accion', 'Confirmar el pedido para asegurar disponibilidad.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('25dbec47-70dd-468a-a361-9bd8876ca491', 'Obtener confirmación formal', 'verificacion', 'Orden de compra, escrito o reserva.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('25dbec47-70dd-468a-a361-9bd8876ca491', 'Si no confirma', 'accion', 'Vuelve a zona gris.', false, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Registrar pedido en sistema', 'accion', 'Cargar pedido completo.', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Confirmar stock', 'verificacion', 'Verificar disponibilidad.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Confirmar condiciones', 'verificacion', 'Precio, descuentos, forma de pago.', true, 2);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Coordinar entrega', 'accion', 'Fecha, lugar y logística.', true, 3);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Confirmar forma de pago', 'verificacion', 'Modalidad de pago acordada.', true, 4);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Confirmación final al cliente', 'accion', 'Comunicar pedido, producto, hectáreas y fecha.', true, 5);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('12782914-8fa9-4e9f-b28b-cfe96e541554', 'Contacto 48hs post-aplicación', 'accion', '¿Cómo viste el resultado? ¿Notaste diferencia?', true, 0);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('12782914-8fa9-4e9f-b28b-cfe96e541554', 'Registrar feedback', 'accion', 'Resultado de aplicación y satisfacción.', true, 1);
INSERT INTO playbook_steps (stage_id, title, type, content, is_required, sort_order) VALUES ('12782914-8fa9-4e9f-b28b-cfe96e541554', 'Detectar próxima oportunidad', 'tip', 'Acompañar la campaña. Identificar próximas necesidades.', true, 2);
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Apertura de llamada', 'Lead nuevo consulta', 'Hola ___, ¿cómo estás?
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Micro-encuadre técnico', 'Instalar autoridad técnica', 'Antes de pasarte números, quiero entender bien el lote y el momento del cultivo así te asesoro correctamente.', 'Eleva el estándar y evita guerra de precios.', 1);
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Diagnóstico técnico', 'Obtener datos del lote', '¿Qué cultivo estás trabajando?
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Situación actual', 'Clasificar proveedores', '¿Ya venís trabajando con algún proveedor o estás evaluando alternativas?', 'Clasificar: Fiel / Comparando / Sin proveedor estable.', 3);
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Nivel de decisión', 'Detectar intención real', 'Si la propuesta cierra técnica y económicamente, ¿estás en condiciones de definir ahora o lo estás evaluando con más tiempo?', NULL, 4);
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'Venta del próximo paso', 'Cerrar con día y hora', 'Con lo que me contás, prefiero prepararte una propuesta bien ajustada y no tirarte un precio al aire.
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '427c93bf-4902-4196-8ca0-c8a7a3cce717', 'WhatsApp #1', 'Lead no atendió', 'Hola ___, soy ___ de [Empresa].
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '427c93bf-4902-4196-8ca0-c8a7a3cce717', 'WhatsApp #2 - Cierre', 'Último intento', 'Intenté comunicarme para asesorarte correctamente.
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c50a5b85-c79c-46b3-854c-72a2695517b7', 'Reencuadre zona gris', 'Productor indeciso', 'Entiendo que lo estés evaluando.
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '25dbec47-70dd-468a-a361-9bd8876ca491', 'Intento de cierre', 'Cliente interesado', 'Con lo que vimos y si estás de acuerdo, el paso lógico sería confirmar el pedido así aseguramos disponibilidad.', NULL, 9);
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '459e8de4-672e-4ad9-beb1-58b0dab24e22', 'Confirmación final', 'Pedido confirmado', 'Perfecto, queda confirmado el pedido de ___ para ___ hectáreas.
INSERT INTO playbook_scripts (playbook_id, stage_id, name, situation, script_text, notes, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '12782914-8fa9-4e9f-b28b-cfe96e541554', 'Seguimiento 48hs', 'Post-aplicación', '¿Cómo viste el resultado?
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c20aad36-f2bf-495a-8346-a0370e3263cd', 'situacion', '¿Qué venís aplicando hoy?', 'Entender tratamiento actual', 'Productos, dosis, frecuencia', '¿Y cómo te está funcionando?', 0);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c20aad36-f2bf-495a-8346-a0370e3263cd', 'problema', '¿Qué problema puntual estás viendo en el lote?', 'Identificar el dolor concreto', 'Plagas, malezas, enfermedades, rendimiento', '¿Desde cuándo lo venís notando?', 1);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c20aad36-f2bf-495a-8346-a0370e3263cd', 'implicacion', 'Si no lo corregís ahora, ¿qué impacto en rendimiento?', 'Cuantificar costo de no actuar', 'Pérdida en qq/ha, riesgo', '¿Cuánto estimás que te cuesta por hectárea?', 2);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c20aad36-f2bf-495a-8346-a0370e3263cd', 'necesidad', '¿Qué resultado esperás lograr con esta aplicación?', 'Definir éxito del productor', 'Rendimiento, control, costo-beneficio', '¿Cuál sería el escenario ideal?', 3);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'situacion', '¿Qué cultivo estás trabajando?', 'Dato básico', 'Soja, maíz, trigo, girasol', NULL, 4);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'situacion', '¿Cuántas hectáreas?', 'Determinar volumen', 'Número concreto', NULL, 5);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'situacion', '¿En qué zona productiva?', 'Evaluar logística', 'Zona núcleo, marginal', NULL, 6);
INSERT INTO playbook_questions (playbook_id, stage_id, category, question, purpose, what_to_listen, followup_question, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'problema', '¿Ya tenés proveedor o estás evaluando?', 'Situación competitiva', 'Fiel, comparando, sin proveedor', NULL, 7);
INSERT INTO playbook_objections (playbook_id, objection, category, severity, responses, signals_working, if_not_working, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'Ya tengo proveedor', 'competencia', 'alta', '[{"type": "reencuadre", "text": "No busco reemplazar a tu proveedor. Muchos productores trabajan con m\u00e1s de uno para tener alternativas.", "example": "Varios clientes de la zona trabajan con 2-3 proveedores."}, {"type": "pregunta", "text": "\u00bfQu\u00e9 es lo que m\u00e1s valor\u00e1s de tu proveedor actual?", "example": null}]'::jsonb, 'El productor empieza a comparar abiertamente', 'Dejar puerta abierta para próxima campaña.', 0);
INSERT INTO playbook_objections (playbook_id, objection, category, severity, responses, signals_working, if_not_working, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'Está muy caro', 'precio', 'alta', '[{"type": "reencuadre", "text": "\u00bfComparado con qu\u00e9 referencia? El costo por hect\u00e1rea var\u00eda mucho seg\u00fan dosis y resultado.", "example": null}, {"type": "evidencia", "text": "Si miramos el costo por quintal producido, nuestra soluci\u00f3n rinde m\u00e1s.", "example": "En un lote similar, el costo fue $X/ha pero el rinde subi\u00f3 Y qq."}]'::jsonb, 'Pide ver los números en detalle', 'No bajar precio. Volver a valor técnico.', 1);
INSERT INTO playbook_objections (playbook_id, objection, category, severity, responses, signals_working, if_not_working, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'Lo tengo que pensar', 'indecision', 'media', '[{"type": "pregunta", "text": "\u00bfQu\u00e9 es lo que te gustar\u00eda evaluar puntualmente?", "example": null}, {"type": "reencuadre", "text": "Lo importante es no perder la ventana de aplicaci\u00f3n. \u00bfLo definimos el jueves?", "example": null}]'::jsonb, 'Acepta fecha concreta', 'Si no define en 7 días, zona gris vencida.', 2);
INSERT INTO playbook_objections (playbook_id, objection, category, severity, responses, signals_working, if_not_working, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'Estoy esperando que llueva', 'timing', 'media', '[{"type": "reencuadre", "text": "Justamente por eso conviene tener el producto reservado para aplicar apenas se d\u00e9 la ventana.", "example": null}]'::jsonb, 'Acepta reservar producto', 'Mantener contacto semanal.', 3);
INSERT INTO playbook_objections (playbook_id, objection, category, severity, responses, signals_working, if_not_working, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'Necesito financiamiento', 'precio', 'media', '[{"type": "reencuadre", "text": "Tenemos opciones de financiamiento. \u00bfQu\u00e9 plazo te servir\u00eda?", "example": null}, {"type": "concesion", "text": "Podemos armar un plan de pago en cuotas atado a cosecha.", "example": null}]'::jsonb, 'Acepta ver opciones', 'Preparar propuesta con condiciones flexibles.', 4);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '9fceea60-80b8-4957-86bc-587852b4939f', 'checklist', 'Checklist operativo inmediato', '{"items": ["Registrar en CRM", "Asignarse como responsable", "Ver producto consultado", "Ver zona productiva", "Identificar si ya es cliente", "Revisar historial de compras"], "note": "Tiempo m\u00e1x: Ideal < 15 min, Aceptable < 1 hora."}'::jsonb, 0);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '628ae25f-3eff-498d-9573-a68b5b2719e8', 'checklist', 'Checklist de calificación', '{"items": ["Cultivo", "Hect\u00e1reas", "Zona", "Estado del cultivo", "Si ya tiene proveedor", "Nivel de decisi\u00f3n", "Volumen estimado"], "note": "Si no puede responder esto \u2192 no puede cotizar."}'::jsonb, 1);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'd4172612-648d-4757-9d06-f43ac0d8547b', 'checklist', 'Criterios de NO calificación', '{"items": ["Volumen m\u00ednimo irrelevante", "Solo pide precio sin datos", "Fuera de zona log\u00edstica", "Solo busca comparaci\u00f3n informal"], "note": "Si alguno aplica \u2192 no califica."}'::jsonb, 2);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c20aad36-f2bf-495a-8346-a0370e3263cd', 'checklist', 'Registrar en visita', '{"items": ["Problema concreto del lote", "Riesgo productivo", "Rendimiento esperado", "Presupuesto impl\u00edcito"], "note": "Regla de oro: mientras m\u00e1s claro el problema, menos se habla de precio."}'::jsonb, 3);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', 'c50a5b85-c79c-46b3-854c-72a2695517b7', 'checklist', 'Prohibiciones en Zona Gris', '{"items": ["NO bajar precio sin criterio", "NO competir por WhatsApp", "NO mandar lista completa", "NO descontar sin volumen confirmado"], "note": "M\u00e1ximo 7 d\u00edas. Siempre dejar pr\u00f3xima acci\u00f3n agendada."}'::jsonb, 4);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '459e8de4-672e-4ad9-beb1-58b0dab24e22', 'checklist', 'Checklist de entrega', '{"items": ["Registrar pedido", "Confirmar stock", "Confirmar condiciones", "Coordinar entrega", "Confirmar forma de pago", "Confirmaci\u00f3n al cliente"], "note": null}'::jsonb, 5);
INSERT INTO playbook_items (playbook_id, stage_id, item_type, title, content, sort_order) VALUES ('a43b65e5-7262-4f3b-ba6a-b8e119d58b2d', '12782914-8fa9-4e9f-b28b-cfe96e541554', 'resource', 'Mensaje para el equipo', '{"items": ["No gana el que pasa precio primero", "Gana el que diagnostica mejor", "Gana el que entiende el lote", "Gana el que ordena la decisi\u00f3n"], "note": "La venta se gana con conocimiento t\u00e9cnico y acompa\u00f1amiento."}'::jsonb, 6);
